def skill():
    tot = 0
    for t in range(1, 4):
        for aw in range(t + 1):
            ab = t - aw
            if aw <= 5 and ab <= 4:
                tot += (5 - aw + 1) * (4 - ab + 1) - 2
    return tot

def standard():
    n = 0
    for aw in range(6):
        for ab in range(5):
            for bw in range(6 - aw):
                for bb in range(5 - ab):
                    cw, cb = 5 - aw - bw, 4 - ab - bb
                    if 1 <= aw + ab <= 3 and bw + bb >= 1 and cw + cb >= 1:
                        n += 1
    return n

def unique():
    return [standard()]
